package toml

import (
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"
)

// value reads the value of a key/value pair.
func (p *parser) value() any {
	if p.eof() || p.peek() == '\n' || p.peek() == '\r' || p.peek() == '#' {
		p.fail(p.pos, "expected a value after '='")
	}
	switch c := p.peek(); {
	case c == '"':
		if strings.HasPrefix(string(p.src[p.pos:]), `"""`) {
			p.fail(p.pos, "multi-line strings are not supported")
		}
		return p.basicString()
	case c == '\'':
		if strings.HasPrefix(string(p.src[p.pos:]), "'''") {
			p.fail(p.pos, "multi-line strings are not supported")
		}
		return p.literalString()
	case c == 't' || c == 'f':
		return p.boolean()
	case c == '+' || c == '-' || c >= '0' && c <= '9':
		return p.number()
	case c == '[':
		p.fail(p.pos, "arrays are not supported")
	case c == '{':
		p.fail(p.pos, "inline tables are not supported")
	case c == 'i' || c == 'n':
		p.fail(p.pos, "floats are not supported")
	}
	p.fail(p.pos, "expected a value, found %q", p.rest())
	return nil
}

// basicString reads a string in double quotes on one line, decoding its
// escapes. A control character other than tab is refused, as is an escape
// TOML 1.0 does not define or a \u or \U that names no Unicode scalar
// value.
func (p *parser) basicString() string {
	start := p.pos
	p.pos++ // '"'
	var b strings.Builder
	for {
		if p.eof() || p.peek() == '\n' || p.peek() == '\r' {
			p.fail(start, "unterminated string")
		}
		c := p.peek()
		switch {
		case c == '"':
			p.pos++
			return b.String()
		case c == '\\':
			p.escape(&b)
		case isControl(c):
			p.fail(p.pos, "control character %U in a string", rune(c))
		default:
			b.WriteByte(c)
			p.pos++
		}
	}
}

// escape decodes one escape sequence in a basic string.
func (p *parser) escape(b *strings.Builder) {
	at := p.pos
	p.pos++ // '\\'
	if p.eof() {
		p.fail(at, "unterminated string")
	}
	c := p.peek()
	p.pos++
	switch c {
	case 'b':
		b.WriteByte('\b')
	case 't':
		b.WriteByte('\t')
	case 'n':
		b.WriteByte('\n')
	case 'f':
		b.WriteByte('\f')
	case 'r':
		b.WriteByte('\r')
	case '"':
		b.WriteByte('"')
	case '\\':
		b.WriteByte('\\')
	case 'u', 'U':
		n := 4
		if c == 'U' {
			n = 8
		}
		if p.pos+n > len(p.src) {
			p.fail(at, "a \\%c escape needs %d hex digits", c, n)
		}
		hex := string(p.src[p.pos : p.pos+n])
		v, err := strconv.ParseUint(hex, 16, 32)
		if err != nil || strings.ContainsAny(hex, "+-") {
			p.fail(at, "a \\%c escape needs %d hex digits", c, n)
		}
		if !utf8.ValidRune(rune(v)) {
			p.fail(at, "\\%c%s is not a Unicode scalar value", c, hex)
		}
		b.WriteRune(rune(v))
		p.pos += n
	default:
		p.fail(at, "invalid escape \\%c", c)
	}
}

// literalString reads a string in single quotes on one line, exactly as
// written: a backslash is a backslash. A control character other than tab
// is refused.
func (p *parser) literalString() string {
	start := p.pos
	p.pos++ // '\''
	for {
		if p.eof() || p.peek() == '\n' || p.peek() == '\r' {
			p.fail(start, "unterminated string")
		}
		c := p.peek()
		if c == '\'' {
			s := string(p.src[start+1 : p.pos])
			p.pos++
			return s
		}
		if isControl(c) {
			p.fail(p.pos, "control character %U in a string", rune(c))
		}
		p.pos++
	}
}

// boolean reads true or false, lower case only.
func (p *parser) boolean() bool {
	for _, w := range []string{"true", "false"} {
		if strings.HasPrefix(string(p.src[p.pos:]), w) {
			end := p.pos + len(w)
			if end == len(p.src) || !isBare(p.src[end]) {
				p.pos = end
				return w == "true"
			}
		}
	}
	p.fail(p.pos, "expected a value, found %q", p.rest())
	return false
}

var decimal = regexp.MustCompile(`^[+-]?(0|[1-9][0-9]*)$`)

// number reads an integer: decimal, with an optional sign, no leading
// zeros, within 64 bits. Every other number TOML has is refused by name.
func (p *parser) number() int64 {
	start := p.pos
	for !p.eof() && strings.IndexByte("0123456789abcdefABCDEFxoinIN_+-.:", p.peek()) >= 0 {
		p.pos++
	}
	tok := string(p.src[start:p.pos])
	if decimal.MatchString(tok) {
		v, err := strconv.ParseInt(tok, 10, 64)
		if err != nil {
			p.fail(start, "integer %s does not fit in 64 bits", tok)
		}
		return v
	}
	unsigned := strings.TrimLeft(tok, "+-")
	switch {
	case strings.Contains(tok, ":") || len(unsigned) >= 10 && unsigned[4] == '-' && !strings.ContainsAny(tok[:1], "+-"):
		p.fail(start, "dates and times are not supported")
	case strings.HasPrefix(unsigned, "0x") || strings.HasPrefix(unsigned, "0o") || strings.HasPrefix(unsigned, "0b"):
		p.fail(start, "hexadecimal, octal and binary integers are not supported")
	case strings.ContainsAny(unsigned, ".eEin"):
		p.fail(start, "floats are not supported")
	case strings.Contains(tok, "_"):
		p.fail(start, "underscores in numbers are not supported")
	}
	p.fail(start, "invalid number %q", tok)
	return 0
}
package toml

import (
	"testing"
)

func TestShortEscapesDecode(t *testing.T) {
	decodes(t, `s = "\b\t\n\f\r\"\\"`+"\n", map[string]any{"s": "\b\t\n\f\r\"\\"})
}

func TestUnicodeEscapesDecode(t *testing.T) {
	decodes(t, `s = "caf\u00E9 \U0001F600"`+"\n", map[string]any{"s": "café 😀"})
}

func TestAnUnknownEscapeIsRefused(t *testing.T) {
	for _, s := range []string{`\x41`, `\e`, `\q`, `\ `} {
		refused(t, `s = "`+s+`"`+"\n", "invalid escape")
	}
}

func TestASurrogateEscapeIsRefused(t *testing.T) {
	refused(t, `s = "\uD800"`+"\n", "scalar value")
	refused(t, `s = "\U00110000"`+"\n", "scalar value")
}

func TestABasicStringIsOneLine(t *testing.T) {
	refused(t, "s = \"no end\nt = 1\n", "unterminated")
	refused(t, "s = \"no end", "unterminated")
}

func TestAControlCharacterInABasicStringIsRefused(t *testing.T) {
	refused(t, "s = \"a\x00b\"\n", "control character")
	decodes(t, "s = \"a\tb\"\n", map[string]any{"s": "a\tb"})
}

func TestALiteralStringKeepsItsBackslashes(t *testing.T) {
	decodes(t, `p = 'C:\Users\n'`+"\n", map[string]any{"p": `C:\Users\n`})
}

func TestAControlCharacterInALiteralStringIsRefused(t *testing.T) {
	refused(t, "p = 'a\x00b'\n", "control character")
}

func TestSignedDecimalIntegers(t *testing.T) {
	decodes(t, "a = 42\nb = +17\nc = -5\nd = -0\ne = 0\n",
		map[string]any{"a": int64(42), "b": int64(17), "c": int64(-5), "d": int64(0), "e": int64(0)})
}

func TestALeadingZeroIsRefused(t *testing.T) {
	refused(t, "a = 007\n")
	refused(t, "a = +01\n")
}

func TestAnIntegerBeyond64BitsIsRefused(t *testing.T) {
	refused(t, "a = 9223372036854775808\n", "64 bits")
	decodes(t, "a = -9223372036854775808\n", map[string]any{"a": int64(-9223372036854775808)})
}

func TestBooleansAreLowerCase(t *testing.T) {
	decodes(t, "a = true\nb = false\n", map[string]any{"a": true, "b": false})
	for _, v := range []string{"True", "FALSE", "truthy", "t"} {
		refused(t, "a = "+v+"\n")
	}
}

func TestFloatsAreRefusedByName(t *testing.T) {
	for _, v := range []string{"3.14", "1e6", "-2.5E-3", "inf", "nan", "+inf"} {
		refused(t, "a = "+v+"\n", "floats")
	}
}

func TestArraysAreRefusedByName(t *testing.T) {
	refused(t, "a = [1, 2]\n", "arrays")
	refused(t, "[[t]]\n", "arrays of tables")
}

func TestDatesAreRefusedByName(t *testing.T) {
	for _, v := range []string{"1979-05-27", "1979-05-27T07:32:00Z", "07:32:00"} {
		refused(t, "a = "+v+"\n", "dates and times")
	}
}

func TestOtherUnbuiltFormsAreRefusedByName(t *testing.T) {
	refused(t, "a = 0xff\n", "hexadecimal")
	refused(t, "a = 1_000\n", "underscores")
	refused(t, "a = \"\"\"x\"\"\"\n", "multi-line strings")
	refused(t, "a = '''x'''\n", "multi-line strings")
	refused(t, "a = { b = 1 }\n", "inline tables")
}
// Package toml decodes TOML documents.
//
// It implements a subset of TOML 1.0 (https://toml.io/en/v1.0.0):
// comments, bare, quoted and dotted keys, single-line basic and literal
// strings, decimal integers, booleans and standard tables. A document that
// uses any other part of TOML is refused with an error that names it.
package toml

// Decode parses a TOML document and returns its root table. Tables are
// map[string]any; strings are string, integers int64 and booleans bool.
// A document that is not valid TOML, or that uses a part of TOML this
// package does not implement, is refused with a *ParseError and no table.
func Decode(data []byte) (doc map[string]any, err error) {
	p := &parser{src: data}
	defer func() {
		if r := recover(); r != nil {
			pe, ok := r.(*ParseError)
			if !ok {
				panic(r)
			}
			doc, err = nil, pe
		}
	}()
	p.parse()
	return p.root.export(), nil
}

// parser holds the state of one Decode: the source, the read position,
// the root table and the table key/value pairs currently go into.
type parser struct {
	src  []byte
	pos  int
	root *table
	cur  *table
}

// parse reads the whole document, one line at a time: blank lines and
// comments, table headers, and key/value pairs.
func (p *parser) parse() {
	p.checkEncoding()
	p.root = &table{origin: defined}
	p.cur = p.root
	for {
		p.skipSpace()
		if p.eof() {
			return
		}
		switch c := p.peek(); {
		case c == '#' || c == '\n' || c == '\r':
			p.lineEnd()
		case c == '[':
			p.header()
			p.lineEnd()
		default:
			p.keyValue()
			p.lineEnd()
		}
	}
}

// keyValue reads one key/value pair and stores it in the current table.
func (p *parser) keyValue() {
	at := p.pos
	path := p.key()
	p.skipSpace()
	if p.eof() || p.peek() != '=' {
		p.fail(p.pos, "expected '=' after the key")
	}
	p.pos++
	p.skipSpace()
	v := p.value()
	p.assign(path, v, at)
}
// Command toml-decoder speaks toml-test's decoder protocol: it reads a TOML
// document on stdin and writes it on stdout as tagged JSON, every value an
// object {"type": ..., "value": ...}. A document it refuses is reported on
// stderr with a non-zero exit, and nothing is written on stdout.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strconv"

	"example.com/toml"
)

func main() {
	os.Exit(run(os.Stdin, os.Stdout, os.Stderr))
}

// run is the command: it returns the exit code.
func run(in io.Reader, out, errOut io.Writer) int {
	data, err := io.ReadAll(in)
	if err != nil {
		fmt.Fprintln(errOut, err)
		return 2
	}
	doc, err := toml.Decode(data)
	if err != nil {
		fmt.Fprintln(errOut, err)
		return 1
	}
	enc := json.NewEncoder(out)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(tag(doc)); err != nil {
		fmt.Fprintln(errOut, err)
		return 2
	}
	return 0
}

// tag turns a decoded value into toml-test's tagged JSON.
func tag(v any) any {
	switch v := v.(type) {
	case map[string]any:
		out := make(map[string]any, len(v))
		for k, e := range v {
			out[k] = tag(e)
		}
		return out
	case string:
		return map[string]string{"type": "string", "value": v}
	case int64:
		return map[string]string{"type": "integer", "value": strconv.FormatInt(v, 10)}
	case bool:
		return map[string]string{"type": "bool", "value": strconv.FormatBool(v)}
	default:
		panic(fmt.Sprintf("toml-decoder: no tag for %T", v))
	}
}
package toml

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

// decodes decodes src and fails the test unless it decodes to want.
func decodes(t *testing.T, src string, want map[string]any) {
	t.Helper()
	got, err := Decode([]byte(src))
	if err != nil {
		t.Fatalf("Decode(%q): %v", src, err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Decode(%q)\n got %#v\nwant %#v", src, got, want)
	}
}

// refused decodes src and fails the test unless it is refused with a
// *ParseError whose message contains each of words. It returns the error.
func refused(t *testing.T, src string, words ...string) *ParseError {
	t.Helper()
	got, err := Decode([]byte(src))
	if err == nil {
		t.Fatalf("Decode(%q) = %#v, want it refused", src, got)
	}
	var pe *ParseError
	if !errors.As(err, &pe) {
		t.Fatalf("Decode(%q): error %T, want *ParseError", src, err)
	}
	for _, w := range words {
		if !strings.Contains(pe.Msg, w) {
			t.Errorf("Decode(%q): message %q does not name %q", src, pe.Msg, w)
		}
	}
	return pe
}
package main

import (
	"bytes"
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

// decoder runs the command as toml-test does: the document on stdin, the
// tagged JSON on stdout.
func decoder(t *testing.T, doc string) (stdout, stderr string, code int) {
	t.Helper()
	var out, errOut bytes.Buffer
	code = run(strings.NewReader(doc), &out, &errOut)
	return out.String(), errOut.String(), code
}

// tagged decodes the command's stdout, failing unless it exited 0.
func tagged(t *testing.T, doc string) map[string]any {
	t.Helper()
	out, errOut, code := decoder(t, doc)
	if code != 0 {
		t.Fatalf("exit %d: %s", code, errOut)
	}
	var v map[string]any
	if err := json.Unmarshal([]byte(out), &v); err != nil {
		t.Fatalf("stdout is not JSON: %v\n%s", err, out)
	}
	return v
}

func val(typ, v string) map[string]any { return map[string]any{"type": typ, "value": v} }

func TestAConfigFileDecodes(t *testing.T) {
	doc := `# The service's configuration
title = "TOML \"example\""
"quoted key" = 'C:\temp'
owner.name = "Tom"

[server]
port = 8080  # the default
debug = false

[server.limits]
max-conns = -1
`
	want := map[string]any{
		"title":      val("string", `TOML "example"`),
		"quoted key": val("string", `C:\temp`),
		"owner":      map[string]any{"name": val("string", "Tom")},
		"server": map[string]any{
			"port":   val("integer", "8080"),
			"debug":  val("bool", "false"),
			"limits": map[string]any{"max-conns": val("integer", "-1")},
		},
	}
	if got := tagged(t, doc); !reflect.DeepEqual(got, want) {
		t.Errorf("got %v\nwant %v", got, want)
	}
}

func TestTypesAreKept(t *testing.T) {
	got := tagged(t, "a = \"42\"\nb = 42\n")
	if !reflect.DeepEqual(got["a"], val("string", "42")) || !reflect.DeepEqual(got["b"], val("integer", "42")) {
		t.Errorf("got %v, want a string 42 and an integer 42", got)
	}
}

func TestARefusalSaysWhere(t *testing.T) {
	out, errOut, code := decoder(t, "name = 'a'\nport = 1\nname = 'b'\n")
	if code == 0 || out != "" {
		t.Errorf("exit %d, stdout %q; want a failing exit and nothing on stdout", code, out)
	}
	if !strings.Contains(errOut, "line 3, column 1") {
		t.Errorf("stderr %q does not say line 3, column 1", errOut)
	}
}

package toml

import "unicode/utf8"

// checkEncoding refuses a document that is not UTF-8 and skips a leading
// byte order mark.
func (p *parser) checkEncoding() {
	if len(p.src) >= 3 && p.src[0] == 0xEF && p.src[1] == 0xBB && p.src[2] == 0xBF {
		p.src = p.src[3:]
	}
	for i := 0; i < len(p.src); {
		r, n := utf8.DecodeRune(p.src[i:])
		if r == utf8.RuneError && n <= 1 {
			p.fail(i, "the document is not valid UTF-8")
		}
		i += n
	}
}

func (p *parser) eof() bool  { return p.pos >= len(p.src) }
func (p *parser) peek() byte { return p.src[p.pos] }

// skipSpace skips whitespace, which in TOML is space and tab only.
func (p *parser) skipSpace() {
	for !p.eof() && (p.peek() == ' ' || p.peek() == '\t') {
		p.pos++
	}
}

// lineEnd reads what may follow a key/value pair or a header: whitespace,
// an optional comment, then a newline (LF or CRLF) or the end of the
// document. Anything else on the line is refused.
func (p *parser) lineEnd() {
	p.skipSpace()
	if p.eof() {
		return
	}
	if p.peek() == '#' {
		p.comment()
		if p.eof() {
			return
		}
	}
	switch {
	case p.peek() == '\n':
		p.pos++
	case p.peek() == '\r' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '\n':
		p.pos += 2
	case p.peek() == '\r':
		p.fail(p.pos, "a carriage return must be followed by a newline")
	default:
		p.fail(p.pos, "expected the end of the line, found %q", p.rest())
	}
}

// comment skips a comment, from # to the end of the line. A control
// character other than tab is refused inside it.
func (p *parser) comment() {
	p.pos++ // '#'
	for !p.eof() {
		c := p.peek()
		if c == '\n' || (c == '\r' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '\n') {
			return
		}
		if isControl(c) {
			p.fail(p.pos, "control character %U in a comment", rune(c))
		}
		p.pos++
	}
}

// isControl reports whether c is a control character TOML forbids in
// comments and strings: U+0000 to U+001F other than tab, and U+007F.
func isControl(c byte) bool {
	return (c < 0x20 && c != '\t') || c == 0x7F
}

// rest is the remainder of the current line, for error messages.
func (p *parser) rest() string {
	end := p.pos
	for end < len(p.src) && p.src[end] != '\n' && end-p.pos < 20 {
		end++
	}
	return string(p.src[p.pos:end])
}

