// Package toml decodes TOML documents.
//
// It implements a subset of TOML 1.0 (https://toml.io/en/v1.0.0):
// comments, bare, quoted and dotted keys, single-line basic and literal
// strings, decimal integers, booleans and standard tables. A document that
// uses any other part of TOML is refused with an error that names it.
package toml

// Decode parses a TOML document and returns its root table. Tables are
// map[string]any; strings are string, integers int64 and booleans bool.
// A document that is not valid TOML, or that uses a part of TOML this
// package does not implement, is refused with a *ParseError and no table.
func Decode(data []byte) (doc map[string]any, err error) {
	p := &parser{src: data}
	defer func() {
		if r := recover(); r != nil {
			pe, ok := r.(*ParseError)
			if !ok {
				panic(r)
			}
			doc, err = nil, pe
		}
	}()
	p.parse()
	return p.root.export(), nil
}

// parser holds the state of one Decode: the source, the read position,
// the root table and the table key/value pairs currently go into.
type parser struct {
	src  []byte
	pos  int
	root *table
	cur  *table
}

// parse reads the whole document, one line at a time: blank lines and
// comments, table headers, and key/value pairs.
func (p *parser) parse() {
	p.checkEncoding()
	p.root = &table{origin: defined}
	p.cur = p.root
	for {
		p.skipSpace()
		if p.eof() {
			return
		}
		switch c := p.peek(); {
		case c == '#' || c == '\n' || c == '\r':
			p.lineEnd()
		case c == '[':
			p.header()
			p.lineEnd()
		default:
			p.keyValue()
			p.lineEnd()
		}
	}
}

// keyValue reads one key/value pair and stores it in the current table.
func (p *parser) keyValue() {
	at := p.pos
	path := p.key()
	p.skipSpace()
	if p.eof() || p.peek() != '=' {
		p.fail(p.pos, "expected '=' after the key")
	}
	p.pos++
	p.skipSpace()
	v := p.value()
	p.assign(path, v, at)
}
// Command toml-decoder speaks toml-test's decoder protocol: it reads a TOML
// document on stdin and writes it on stdout as tagged JSON, every value an
// object {"type": ..., "value": ...}. A document it refuses is reported on
// stderr with a non-zero exit, and nothing is written on stdout.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strconv"

	"example.com/toml"
)

func main() {
	os.Exit(run(os.Stdin, os.Stdout, os.Stderr))
}

// run is the command: it returns the exit code.
func run(in io.Reader, out, errOut io.Writer) int {
	data, err := io.ReadAll(in)
	if err != nil {
		fmt.Fprintln(errOut, err)
		return 2
	}
	doc, err := toml.Decode(data)
	if err != nil {
		fmt.Fprintln(errOut, err)
		return 1
	}
	enc := json.NewEncoder(out)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(tag(doc)); err != nil {
		fmt.Fprintln(errOut, err)
		return 2
	}
	return 0
}

// tag turns a decoded value into toml-test's tagged JSON.
func tag(v any) any {
	switch v := v.(type) {
	case map[string]any:
		out := make(map[string]any, len(v))
		for k, e := range v {
			out[k] = tag(e)
		}
		return out
	case string:
		return map[string]string{"type": "string", "value": v}
	case int64:
		return map[string]string{"type": "integer", "value": strconv.FormatInt(v, 10)}
	case bool:
		return map[string]string{"type": "bool", "value": strconv.FormatBool(v)}
	default:
		panic(fmt.Sprintf("toml-decoder: no tag for %T", v))
	}
}
package toml

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

// decodes decodes src and fails the test unless it decodes to want.
func decodes(t *testing.T, src string, want map[string]any) {
	t.Helper()
	got, err := Decode([]byte(src))
	if err != nil {
		t.Fatalf("Decode(%q): %v", src, err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Decode(%q)\n got %#v\nwant %#v", src, got, want)
	}
}

// refused decodes src and fails the test unless it is refused with a
// *ParseError whose message contains each of words. It returns the error.
func refused(t *testing.T, src string, words ...string) *ParseError {
	t.Helper()
	got, err := Decode([]byte(src))
	if err == nil {
		t.Fatalf("Decode(%q) = %#v, want it refused", src, got)
	}
	var pe *ParseError
	if !errors.As(err, &pe) {
		t.Fatalf("Decode(%q): error %T, want *ParseError", src, err)
	}
	for _, w := range words {
		if !strings.Contains(pe.Msg, w) {
			t.Errorf("Decode(%q): message %q does not name %q", src, pe.Msg, w)
		}
	}
	return pe
}
package main

import (
	"bytes"
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

// decoder runs the command as toml-test does: the document on stdin, the
// tagged JSON on stdout.
func decoder(t *testing.T, doc string) (stdout, stderr string, code int) {
	t.Helper()
	var out, errOut bytes.Buffer
	code = run(strings.NewReader(doc), &out, &errOut)
	return out.String(), errOut.String(), code
}

// tagged decodes the command's stdout, failing unless it exited 0.
func tagged(t *testing.T, doc string) map[string]any {
	t.Helper()
	out, errOut, code := decoder(t, doc)
	if code != 0 {
		t.Fatalf("exit %d: %s", code, errOut)
	}
	var v map[string]any
	if err := json.Unmarshal([]byte(out), &v); err != nil {
		t.Fatalf("stdout is not JSON: %v\n%s", err, out)
	}
	return v
}

func val(typ, v string) map[string]any { return map[string]any{"type": typ, "value": v} }

func TestAConfigFileDecodes(t *testing.T) {
	doc := `# The service's configuration
title = "TOML \"example\""
"quoted key" = 'C:\temp'
owner.name = "Tom"

[server]
port = 8080  # the default
debug = false

[server.limits]
max-conns = -1
`
	want := map[string]any{
		"title":      val("string", `TOML "example"`),
		"quoted key": val("string", `C:\temp`),
		"owner":      map[string]any{"name": val("string", "Tom")},
		"server": map[string]any{
			"port":   val("integer", "8080"),
			"debug":  val("bool", "false"),
			"limits": map[string]any{"max-conns": val("integer", "-1")},
		},
	}
	if got := tagged(t, doc); !reflect.DeepEqual(got, want) {
		t.Errorf("got %v\nwant %v", got, want)
	}
}

func TestTypesAreKept(t *testing.T) {
	got := tagged(t, "a = \"42\"\nb = 42\n")
	if !reflect.DeepEqual(got["a"], val("string", "42")) || !reflect.DeepEqual(got["b"], val("integer", "42")) {
		t.Errorf("got %v, want a string 42 and an integer 42", got)
	}
}

func TestARefusalSaysWhere(t *testing.T) {
	out, errOut, code := decoder(t, "name = 'a'\nport = 1\nname = 'b'\n")
	if code == 0 || out != "" {
		t.Errorf("exit %d, stdout %q; want a failing exit and nothing on stdout", code, out)
	}
	if !strings.Contains(errOut, "line 3, column 1") {
		t.Errorf("stderr %q does not say line 3, column 1", errOut)
	}
}

package toml

import "unicode/utf8"

// checkEncoding refuses a document that is not UTF-8 and skips a leading
// byte order mark.
func (p *parser) checkEncoding() {
	if len(p.src) >= 3 && p.src[0] == 0xEF && p.src[1] == 0xBB && p.src[2] == 0xBF {
		p.src = p.src[3:]
	}
	for i := 0; i < len(p.src); {
		r, n := utf8.DecodeRune(p.src[i:])
		if r == utf8.RuneError && n <= 1 {
			p.fail(i, "the document is not valid UTF-8")
		}
		i += n
	}
}

func (p *parser) eof() bool  { return p.pos >= len(p.src) }
func (p *parser) peek() byte { return p.src[p.pos] }

// skipSpace skips whitespace, which in TOML is space and tab only.
func (p *parser) skipSpace() {
	for !p.eof() && (p.peek() == ' ' || p.peek() == '\t') {
		p.pos++
	}
}

// lineEnd reads what may follow a key/value pair or a header: whitespace,
// an optional comment, then a newline (LF or CRLF) or the end of the
// document. Anything else on the line is refused.
func (p *parser) lineEnd() {
	p.skipSpace()
	if p.eof() {
		return
	}
	if p.peek() == '#' {
		p.comment()
		if p.eof() {
			return
		}
	}
	switch {
	case p.peek() == '\n':
		p.pos++
	case p.peek() == '\r' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '\n':
		p.pos += 2
	case p.peek() == '\r':
		p.fail(p.pos, "a carriage return must be followed by a newline")
	default:
		p.fail(p.pos, "expected the end of the line, found %q", p.rest())
	}
}

// comment skips a comment, from # to the end of the line. A control
// character other than tab is refused inside it.
func (p *parser) comment() {
	p.pos++ // '#'
	for !p.eof() {
		c := p.peek()
		if c == '\n' || (c == '\r' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '\n') {
			return
		}
		if isControl(c) {
			p.fail(p.pos, "control character %U in a comment", rune(c))
		}
		p.pos++
	}
}

// isControl reports whether c is a control character TOML forbids in
// comments and strings: U+0000 to U+001F other than tab, and U+007F.
func isControl(c byte) bool {
	return (c < 0x20 && c != '\t') || c == 0x7F
}

// rest is the remainder of the current line, for error messages.
func (p *parser) rest() string {
	end := p.pos
	for end < len(p.src) && p.src[end] != '\n' && end-p.pos < 20 {
		end++
	}
	return string(p.src[p.pos:end])
}

