		"1.", "1.e5", "1e", "1e+", "1.5.3", "03.14", "-01.0", "00e1",
		"1__0.0", "_1.0", "1_.0", "1._0", "1.0_", "1e_5", "1e5_",
		"+-1.0", "1.0e5.5", "1e5e5", "++inf", "infinity", "nanx", "inf2",
	} {
		refused(t, "a = "+v+"\\n")
	}
	for _, v := range []string{".5", "Inf", "NaN", "INF", "-.5e1"} {
		refused(t, "a = "+v+"\\n")
	}
}

func TestAFloatBeyond64BitsIsRefused(t *testing.T) {
	refused(t, "a = 1e400\\n", "too large")
	refused(t, "a = -1.8e308\\n", "too large")
	decodes(t, "a = 1.7976931348623157e308\\n", map[string]any{"a": 1.7976931348623157e308})
}

func TestFloatsDoNotEatDatesOrHex(t *testing.T) {
	refused(t, "a = 1979-05-27\\n", "dates and times")
	refused(t, "a = 0xbeef\\n", "hexadecimal")
}

